//! Replay the pinned CesiumJS `ShadowMap` constructor and CPU camera/cascade
//! fitting cases in `tests/data/scene-shadow-map.json` (generated by
//! `tools/cesium/generate-scene-shadow-map.mjs`).

mod common;

use cesium_rs::{
    core::{webgl_constants as gl, *},
    renderer::{self, Context, Gl, GlValue, UniformCamera, UniformFrame},
    scene::{
        shadow_map::{ShadowBias, ShadowMap, ShadowMapFrustum, ShadowMapLightCamera},
        FramePasses, FrameResource, FrameState, SceneMode,
    },
};
use common::{c3, m4, n};
use serde_json::Value;
use std::{
    cell::{Cell, RefCell},
    collections::HashMap,
};

#[derive(Default)]
struct ShadowGl {
    next: Cell<u32>,
    values: RefCell<HashMap<u32, GlValue<u32>>>,
}

impl Gl for ShadowGl {
    type Object = u32;
    fn drawing_buffer_size(&self) -> Result<[u32; 2], RuntimeError> {
        Ok([1024, 768])
    }
    fn invoke(&self, method: &str, args: &[GlValue<u32>]) -> Result<GlValue<u32>, RuntimeError> {
        let object = |i: usize| match args.get(i) {
            Some(GlValue::Object(id)) => *id,
            _ => 0,
        };
        let number = |i: usize| match args.get(i) {
            Some(GlValue::Number(n)) => *n,
            _ => 0.0,
        };
        if method.starts_with("create") {
            let next = self.next.get() + 1;
            self.next.set(next);
            self.values.borrow_mut().insert(next, GlValue::Object(next));
            return Ok(GlValue::Object(next));
        }
        Ok(match method {
            "getParameter" => match number(0) as u32 {
                gl::MAX_VIEWPORT_DIMS | gl::ALIASED_LINE_WIDTH_RANGE | gl::ALIASED_POINT_SIZE_RANGE => {
                    GlValue::Numbers(vec![1.0, 16384.0])
                }
                gl::MAX_TEXTURE_SIZE | gl::MAX_CUBE_MAP_TEXTURE_SIZE | gl::MAX_RENDERBUFFER_SIZE => {
                    GlValue::Number(16384.0)
                }
                _ => GlValue::Number(16384.0),
            },
            "getExtension" => GlValue::Object(1),
            "getShaderParameter" | "getProgramParameter" => GlValue::Bool(true),
            "checkFramebufferStatus" => GlValue::Number(f64::from(gl::FRAMEBUFFER_COMPLETE)),
            "getAttribLocation" => GlValue::Number(-1.0),
            "getUniformLocation" => GlValue::Object(0),
            "getActiveAttrib" => GlValue::Record(serde_json::json!({"name": "x", "size": 1, "type": gl::FLOAT})),
            "getActiveUniform" => GlValue::Record(serde_json::json!({"name": "x", "size": 1, "type": gl::FLOAT})),
            "getShaderInfoLog" => GlValue::Null,
            "getShaderSource" | "getProgramInfoLog" => GlValue::Null,
            _ => {
                let _ = object(0);
                GlValue::Null
            }
        })
    }
}

fn fixture() -> Value {
    serde_json::from_str(include_str!("data/scene-shadow-map.json")).unwrap()
}

fn light_camera(value: &Value) -> Result<ShadowMapLightCamera, RuntimeError> {
    let frustum = &value["frustum"];
    Ok(ShadowMapLightCamera {
        view_matrix: m4(&value["view"]),
        inverse_view_matrix: m4(&value["inverseView"]),
        frustum: ShadowMapFrustum::Perspective(PerspectiveFrustum {
            fov: n(&frustum["fov"]),
            aspect_ratio: n(&frustum["aspectRatio"]),
            near: n(&frustum["near"]),
            far: n(&frustum["far"]),
            x_offset: frustum["xOffset"].as_f64().unwrap_or(0.0),
            y_offset: frustum["yOffset"].as_f64().unwrap_or(0.0),
        }),
        position_cartographic: Cartographic::default(),
        position_wc: c3(&value["positionWC"]),
        direction_wc: c3(&value["directionWC"]),
        up_wc: c3(&value["upWC"]),
        right_wc: c3(&value["rightWC"]),
    })
}

fn frame(context: &Context<ShadowGl>, camera: &Value, near: f64, far: f64, closest: f64) -> FrameState {
    let frustum = &camera["frustum"];
    let uniform_camera = UniformCamera {
        view: m4(&camera["view"]),
        inverse_view: m4(&camera["inverseView"]),
        position: c3(&camera["positionWC"]),
        direction: c3(&camera["directionWC"]),
        right: c3(&camera["rightWC"]),
        up: c3(&camera["upWC"]),
        cartographic: None,
        frustum: renderer::UniformFrustum::Perspective(PerspectiveFrustum {
            fov: n(&frustum["fov"]),
            aspect_ratio: n(&frustum["aspectRatio"]),
            near: n(&frustum["near"]),
            far: n(&frustum["far"]),
            x_offset: 0.0,
            y_offset: 0.0,
        }),
    };
    let uniform = UniformFrame::new(uniform_camera, JulianDate::default());
    let culling =
        CullingVolume::from_bounding_sphere(&BoundingSphere::new(Cartesian3::new(7000000.0, 0.0, 0.0), 100.0));
    let mut frame = FrameState::new(uniform, culling, [1024, 768]);
    frame.mode = SceneMode::Scene3D;
    frame.passes = FramePasses { render: true, ..Default::default() };
    frame.context = Some(FrameResource::new(context.clone()));
    frame.stencil_buffer = true;
    frame.shadow_state.near_plane = near;
    frame.shadow_state.far_plane = far;
    frame.shadow_state.closest_object_size = closest;
    frame
}

fn encode_state(state: &renderer::RenderState) -> Value {
    serde_json::json!({
        "cull": {"enabled": state.cull.enabled, "face": state.cull.face},
        "depthTest": {"enabled": state.depth_test.enabled, "func": state.depth_test.func},
        "depthMask": state.depth_mask,
        "colorMask": {"red": state.color_mask.red, "green": state.color_mask.green, "blue": state.color_mask.blue, "alpha": state.color_mask.alpha},
        "polygonOffset": {"enabled": state.polygon_offset.enabled, "factor": state.polygon_offset.factor, "units": state.polygon_offset.units},
        "blending": state.blending.enabled,
        "stencilTest": {
            "enabled": state.stencil_test.enabled,
            "frontFunction": state.stencil_test.front_function,
            "backFunction": state.stencil_test.back_function,
            "reference": state.stencil_test.reference,
            "mask": state.stencil_test.mask,
            "frontOperation": {"fail": state.stencil_test.front_operation.fail, "zFail": state.stencil_test.front_operation.z_fail, "zPass": state.stencil_test.front_operation.z_pass},
            "backOperation": {"fail": state.stencil_test.back_operation.fail, "zFail": state.stencil_test.back_operation.z_fail, "zPass": state.stencil_test.back_operation.z_pass},
        },
        "stencilMask": state.stencil_mask,
    })
}

fn encode_bias(bias: ShadowBias) -> Value {
    serde_json::json!({
        "polygonOffset": bias.polygon_offset,
        "polygonOffsetFactor": bias.polygon_offset_factor,
        "polygonOffsetUnits": bias.polygon_offset_units,
        "normalOffset": bias.normal_offset,
        "normalOffsetScale": bias.normal_offset_scale,
        "normalShading": bias.normal_shading,
        "normalShadingSmooth": bias.normal_shading_smooth,
        "depthBias": bias.depth_bias,
    })
}

fn assert_json_eq(actual: &Value, expected: &Value, label: &str) {
    match (actual, expected) {
        (Value::Number(a), Value::Number(e)) => {
            assert!((a.as_f64().unwrap() - e.as_f64().unwrap()).abs() <= 1e-12, "{label}: {actual} != {expected}")
        }
        (Value::Array(a), Value::Array(e)) => {
            assert_eq!(a.len(), e.len(), "{label}: {actual} != {expected}");
            for (a, e) in a.iter().zip(e) {
                assert_json_eq(a, e, label);
            }
        }
        (Value::Object(a), Value::Object(e)) => {
            assert_eq!(a.len(), e.len(), "{label}: {actual} != {expected}");
            for (key, a) in a {
                assert_json_eq(a, &e[key], label);
            }
        }
        _ => assert_eq!(actual, expected, "{label}"),
    }
}

fn close(a: f64, b: f64) -> bool {
    (a - b).abs() <= 1e-9 * a.abs().max(b.abs()).max(1.0)
}
fn close_slice(actual: &[f64], expected: &[Value]) {
    assert_eq!(actual.len(), expected.len(), "actual {actual:?} expected {expected:?}");
    for (a, e) in actual.iter().zip(expected) {
        let e = n(e);
        assert!(close(*a, e), "{a} != {e}");
    }
}

#[test]
fn maximum_distance_constant() {
    assert_eq!(n(&fixture()["maximumDistance"]), 20000.0);
}

#[test]
fn constructors_match_reference() {
    let fixture = fixture();
    let context = Context::new_webgl2(ShadowGl::default());
    for case in fixture["constructor"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let light = light_camera(&fixture["update"][0]["lightCamera"]).unwrap();
        let point = case["isPointLight"].as_bool().unwrap();
        let cascades = case["passCount"].as_u64().unwrap();
        let size = case["size"].as_u64().unwrap() as u32;
        let shadow = ShadowMap::new(
            context.clone(),
            light,
            Some(case["enabled"].as_bool().unwrap()),
            Some(point),
            Some(250.0),
            Some(cascades == 4 || (cascades == 1 && !point)),
            Some(if cascades == 4 { 4 } else { 1 }),
            Some(n(&case["maximumDistance"])),
            Some(size),
            Some(case["softShadows"].as_bool().unwrap()),
            Some(n(&case["darkness"])),
            Some(case["normalOffset"].as_bool().unwrap()),
            Some(case["fadingEnabled"].as_bool().unwrap()),
        )
        .unwrap();
        assert!(shadow.shadow_map_camera().frustum.near().is_finite(), "{name}");
        assert!(!shadow.out_of_view(), "{name}");
        assert_eq!(shadow.passes().len() as u64, case["passCount"].as_u64().unwrap(), "{name}");
        assert_eq!(shadow.size(), size, "{name}");
        close_slice(&[shadow.texture_size().x, shadow.texture_size().y], case["textureSize"].as_array().unwrap());
        for (pass, expected) in shadow.passes().iter().zip(case["viewports"].as_array().unwrap()) {
            let expected = expected.as_array().unwrap();
            assert_eq!(pass.viewport.x as f64, n(&expected[0]), "{name}");
            assert_eq!(pass.viewport.y as f64, n(&expected[1]), "{name}");
            assert_eq!(pass.viewport.width as f64, n(&expected[2]), "{name}");
            assert_eq!(pass.viewport.height as f64, n(&expected[3]), "{name}");
        }
        for (pass, expected) in shadow.passes().iter().zip(case["textureOffsets"].as_array().unwrap()) {
            if expected.is_null() {
                continue;
            }
            close_slice(&pass.texture_offsets.unwrap().0, expected.as_array().unwrap());
        }
        assert_json_eq(&encode_bias(shadow.primitive_bias()), &case["primitiveBias"], name);
        assert_json_eq(&encode_bias(shadow.terrain_bias()), &case["terrainBias"], name);
        assert_json_eq(&encode_bias(shadow.point_bias()), &case["pointBias"], name);
        assert_json_eq(&encode_state(shadow.primitive_render_state()), &case["primitiveRenderState"], name);
        assert_json_eq(&encode_state(shadow.terrain_render_state()), &case["terrainRenderState"], name);
        assert_json_eq(&encode_state(shadow.point_render_state()), &case["pointRenderState"], name);
    }
}

#[test]
fn update_matches_reference() {
    let fixture = fixture();
    for case in fixture["update"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let context = Context::new_webgl2(ShadowGl::default());
        let light = light_camera(&case["lightCamera"]).unwrap();
        let single = name == "single";
        let mut shadow = ShadowMap::new(
            context.clone(),
            light,
            Some(true),
            Some(false),
            None,
            Some(true),
            Some(if single { 1 } else { 4 }),
            Some(n(&case["lightCamera"]["frustum"]["far"])),
            Some(2048),
            Some(false),
            Some(0.3),
            Some(true),
            Some(true),
        )
        .unwrap();
        let mut frame = frame(
            &context,
            &case["sceneCamera"],
            n(&case["sceneCameraNearFar"][0]),
            n(&case["sceneCameraNearFar"][1]),
            1000.0,
        );
        frame.shadow_state.closest_object_size = match name {
            "cascadesClose" => 100.0,
            _ => 1000.0,
        };
        shadow.update(&frame).unwrap();

        let camera = case["shadowMapCamera"].as_object().unwrap();
        eprintln!("CASE {name} OURVIEW {:?} EXPECT {:?}", shadow.shadow_map_camera().view_matrix.0, camera["view"]);
        close_slice(&shadow.shadow_map_camera().view_matrix.0, camera["view"].as_array().unwrap());
        close_slice(&shadow.shadow_map_camera().inverse_view_matrix.0, camera["inverseView"].as_array().unwrap());
        close_slice(
            &[
                shadow.shadow_map_camera().position_wc.x,
                shadow.shadow_map_camera().position_wc.y,
                shadow.shadow_map_camera().position_wc.z,
            ],
            camera["positionWC"].as_array().unwrap(),
        );
        close_slice(
            &[
                shadow.shadow_map_camera().direction_wc.x,
                shadow.shadow_map_camera().direction_wc.y,
                shadow.shadow_map_camera().direction_wc.z,
            ],
            camera["directionWC"].as_array().unwrap(),
        );
        let frustum = &camera["frustum"];
        if let ShadowMapFrustum::OrthographicOffCenter(f) = shadow.shadow_map_camera().frustum {
            close_slice(
                &[f.left, f.right, f.bottom, f.top, f.near, f.far],
                &[
                    frustum["left"].clone(),
                    frustum["right"].clone(),
                    frustum["bottom"].clone(),
                    frustum["top"].clone(),
                    frustum["near"].clone(),
                    frustum["far"].clone(),
                ],
            );
        }
        close_slice(&[shadow.distance()], &[case["distance"].clone()]);
        assert_eq!(shadow.out_of_view(), case["outOfView"].as_bool().unwrap(), "{name}");
        assert!(close(shadow.darkness_current(), n(&case["darkness"])), "{name}");
        let direction = shadow.light_direction_ec();
        close_slice(&[direction.x, direction.y, direction.z], case["lightDirectionEC"].as_array().unwrap());
        let position = shadow.light_position_ec();
        close_slice(&[position.x, position.y, position.z, position.w], case["lightPositionEC"].as_array().unwrap());
        if single {
            close_slice(&shadow.shadow_map_matrix().0, case["shadowMapMatrix"].as_array().unwrap());
        }

        if !single {
            let splits = shadow.cascade_splits();
            close_slice(
                &[splits[0].x, splits[0].y, splits[0].z, splits[0].w],
                case["cascadeSplits"][0].as_array().unwrap(),
            );
            close_slice(
                &[splits[1].x, splits[1].y, splits[1].z, splits[1].w],
                case["cascadeSplits"][1].as_array().unwrap(),
            );
            let distances = shadow.cascade_distances();
            close_slice(
                &[distances.x, distances.y, distances.z, distances.w],
                case["cascadeDistances"].as_array().unwrap(),
            );
            for (i, expected) in case["cascadeMatrices"].as_array().unwrap().iter().enumerate() {
                close_slice(&shadow.cascade_matrices()[i].0, expected.as_array().unwrap());
            }
            for (pass, expected) in shadow.passes().iter().zip(case["passes"].as_array().unwrap()) {
                close_slice(&pass.camera.view_matrix.0, expected["cameraView"].as_array().unwrap());
                if let ShadowMapFrustum::OrthographicOffCenter(f) = pass.camera.frustum {
                    let frustum = &expected["frustum"];
                    close_slice(
                        &[f.left, f.right, f.bottom, f.top, f.near, f.far],
                        &[
                            frustum["left"].clone(),
                            frustum["right"].clone(),
                            frustum["bottom"].clone(),
                            frustum["top"].clone(),
                            frustum["near"].clone(),
                            frustum["far"].clone(),
                        ],
                    );
                }
                if let (Some(volume), Some(planes)) = (&pass.culling_volume, expected["cullingPlanes"].as_array()) {
                    for (plane, expected) in volume.planes.iter().zip(planes) {
                        close_slice(&[plane.x, plane.y, plane.z, plane.w], expected.as_array().unwrap());
                    }
                }
            }
        }
        if let Some(expected) = case["cullingPlanes"].as_array() {
            let volume = shadow.shadow_map_culling_volume().unwrap();
            for (plane, expected) in volume.planes.iter().zip(expected) {
                close_slice(&[plane.x, plane.y, plane.z, plane.w], expected.as_array().unwrap());
            }
        }
    }
}
